    justifyContent: 'center',
    alignItems: 'center',
  },
  noImageText: {
    fontSize: 16,
    color: '#888',
    marginTop: 8,
  },
  contentContainer: {
    padding: 20,
  },
  title: {
    fontSize: 24,
    fontWeight: 'bold',
    color: '#333333',
    marginBottom: 12,
  },
  publisherContainer: {
    flexDirection: 'row',
    alignItems: 'center',
    marginBottom: 15,
  },
  publisherContainerNoIcon: {
    justifyContent: 'flex-start',
  },
  publisherIcon: {
    width: 40,
    height: 40,
    borderRadius: 20,
    marginRight: 12,
  },
  publisherInfo: {
    flex: 1,
  },
  publisherInfoNoIcon: {
    flex: 0,
    alignSelf: 'flex-start',
  },
  publisherName: {
    fontSize: 16,
    fontWeight: '600',
    color: '#333333',
  },
  publishDate: {
    fontSize: 12,
    color: '#666666',
    marginTop: 2,
  },
  summary: {
    fontSize: 16,
    lineHeight: 24,
    color: '#555',
    marginVertical: 10,
  },
  divider: {
    height: 1,
    backgroundColor: '#e0e0e0',
    marginVertical: 16,
  },
  content: {
    fontSize: 16,
