    onSourceLinkPress();
  }, [onSourceLinkPress]);

  const styles = createStyleSheet(isSmallDevice);

  return (
    <View style={styles.cardContentContainer}>
      {/* White extension area that overlaps the image - similar to Inshorts pattern */}
