          isFocused={state.index === index}
        />
      ))}
    </View>
  );

  // Mock screens
  const mockScreens = {
    Home: ({ navigation }) => (
      <View testID="home-screen">
        <Text>Home Screen</Text>
        <ScrollView testID="feed">
          {[0, 1, 2].map((i) => (
            <TouchableOpacity 
              key={i}
