              onPress={() => navigation.navigate('ArticleDetail', { id: i })}
            >
              <Text>Article {i}</Text>
            </TouchableOpacity>
          ))}
        </ScrollView>
      </View>
    ),
    
    Discover: ({ navigation }) => (
