/**
 * Utility functions for E2E testing
 */
const { element, by, device, expect, waitFor } = require('detox');

// Test data for auth flows
const TEST_USER = {
  email: 'test-user@example.com',
  password: 'Test@123456',
  invalidPassword: 'wrongpassword',
};

/**
 * Helper function to wait for an element with the provided ID to be visible
 * @param {string} id - Test ID of the element to wait for
 * @param {number} timeout - Optional timeout in ms (default: 5000ms)
 */
async function waitForElementById(id, timeout = 5000) {
  await waitFor(element(by.id(id)))
    .toBeVisible()
    .withTimeout(timeout);
}

/**
 * Helper function to wait for an element with the provided text to be visible
 * @param {string} text - Text content of the element to wait for
 * @param {number} timeout - Optional timeout in ms (default: 5000ms)
 */
async function waitForElementByText(text, timeout = 5000) {
  await waitFor(element(by.text(text)))
    .toBeVisible()
    .withTimeout(timeout);
}

/**
 * Helper function to simulate network conditions
 * @param {string} condition - 'online', 'offline', 'slow'
 */
async function setNetworkCondition(condition) {
  if (condition === 'offline') {
    await device.setStatusBar({ network: 'no-network' });
  } else if (condition === 'slow') {
    await device.setStatusBar({ network: 'edge' });
  } else {
    await device.setStatusBar({ network: 'wifi' });
  }
}

/**
 * Perform login with provided credentials
 * @param {string} email - Email address
 * @param {string} password - Password
 */
async function login(email, password) {
  await waitForElementById('email-input');
  await element(by.id('email-input')).typeText(email);
  await element(by.id('password-input')).typeText(password);
  await element(by.id('login-button')).tap();
}

/**
 * Navigate to a specific screen through the bottom tab navigation
 * @param {string} screenName - Name of the screen to navigate to
 */
async function navigateToScreen(screenName) {
  // Map of screen names to tab IDs
  const tabMapping = {
    'Home': 'home-tab',
    'Discover': 'discover-tab',
    'Profile': 'profile-tab',
    'Bookmarks': 'bookmarks-tab',
    'Settings': 'settings-tab',
  };
  
  const tabId = tabMapping[screenName];
  
  if (!tabId) {
    throw new Error(`Screen name "${screenName}" not found in tab mapping`);
  }
  
  await element(by.id(tabId)).tap();
  
  // Wait for the screen to become visible
  await waitForElementById(`${screenName.toLowerCase()}-screen`);
}

/**
 * Logout from the app through the settings menu
 */
async function logout() {
  await navigateToScreen('Settings');
  await element(by.id('logout-button')).tap();
  await element(by.text('Confirm')).tap();
}

/**
 * Check if the user is logged in
 * @returns {Promise<boolean>} - Returns true if user is logged in, false otherwise
 */
async function isLoggedIn() {
  try {
    // Try to find an element that's only visible when logged in
    await waitForElementById('home-screen', 2000);
    return true;
  } catch (error) {
    return false;
  }
}

module.exports = {
  TEST_USER,
  waitForElementById,
  waitForElementByText,
  setNetworkCondition,
  login,
  navigateToScreen,
  logout,
  isLoggedIn
};

import { useEffect, useRef } from 'react';
import { useNavigationContainerRef } from '@react-navigation/native';
import { analyticsService } from '../services/AnalyticsService';
import { ScreenViewAnalyticsParams } from '../src/types/analytics';

/**
 * Hook to automatically track screen views and user navigation patterns.
 * 
 * Tracks:
 * - Initial screen view on app launch
 * - Screen transitions during navigation
 * - Maintains navigation history for analytics
 */
export const useScreenTracking = () => {
  const navigationRef = useNavigationContainerRef();
  const routeNameRef = useRef<string | undefined>();

  useEffect(() => {
    const onReady = () => {
      // This will be called once the navigation container is ready
      const initialRoute = navigationRef.getCurrentRoute();
      if (initialRoute?.name) {
        const screenParams = {
          screen_name: initialRoute.name,
          screen_class: initialRoute.name,
        } as const;
        analyticsService.logScreenView(screenParams);
        routeNameRef.current = initialRoute.name;
        if (__DEV__) {
          console.log(`[Analytics] Initial screen view tracked (onReady): ${initialRoute.name}`);
        }
      }
    };

    const onStateChange = () => {
      if (!navigationRef.isReady()) {
        // Don't do anything if the navigator is not yet ready
        return;
      }
      const previousRouteName = routeNameRef.current;
      const currentRouteName = navigationRef.getCurrentRoute()?.name;

      if (previousRouteName !== currentRouteName && currentRouteName) {
        const screenParams: ScreenViewAnalyticsParams = {
          screen_name: currentRouteName,
          screen_class: currentRouteName,
        };
        analyticsService.logScreenView(screenParams);
        if (__DEV__) {
          console.log(`[Analytics] Screen view tracked (onStateChange): ${currentRouteName}`);
        }
      }
      routeNameRef.current = currentRouteName;
    };

    // Add listener for when the navigator is ready
    // The 'state' event might fire before 'ready', so listening to 'ready' for initial tracking is safer.
    // However, 'ready' is not a standard event on navigationRef directly.
    // Instead, we rely on NavigationContainer's onReady in App.tsx for the *very first* screen.
    // For subsequent state changes after ready, onStateChange will work.

    // We need to ensure that the initial screen is logged *after* the navigator is ready.
    // The App.tsx onReady callback now handles DeepLinkHandler init.
    // useScreenTracking is primarily for ongoing screen changes and initial load if ready.

    if (navigationRef.isReady()) {
      // If already ready when this effect runs, log initial screen
      onReady();
    }
    // else onReady will be called by NavigationContainer in App.tsx, or we can listen for a ready event if available.
    // For now, we'll rely on isReady() check.

    const unsubscribeState = navigationRef.addListener('state', onStateChange);

    return () => {
      unsubscribeState?.();
    };
  }, [navigationRef]);

  return navigationRef;
};

import { useState, useEffect } from 'react';
import { supabase } from '../utils/supabase';
import { Article } from '../types/supabase';
import { useSavedArticles } from '../context/SavedArticlesContext';
import { analyticsService } from '../services/AnalyticsService';

export const useArticle = (articleId: string | null) => {
  const [article, setArticle] = useState<Article | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const {
    savedArticles,
    addBookmark,
    removeBookmark,
    isLoading: isBookmarkLoading,
  } = useSavedArticles();

  const isBookmarked = savedArticles.some(a => a.id === articleId);

  useEffect(() => {
    const fetchArticle = async () => {
      if (!articleId) {
        setLoading(false);
        setError('Article ID is missing.');
        return;
      }

      setLoading(true);
      setError(null);

      try {
        const { data, error: fetchError } = await supabase
          .from('news')
          .select('*, category:category_id(*)')
          .eq('id', articleId)
          .single();

        if (fetchError) {
          throw fetchError;
        }

        if (data) {
          setArticle(data as Article);
        } else {
          setError('Article not found.');
        }
      } catch (e: any) {
        setError(e.message || 'Failed to fetch article.');
        console.error('Error fetching article:', e);
      } finally {
        setLoading(false);
      }
    };

    fetchArticle();
  }, [articleId]);

  const toggleBookmark = async () => {
    if (!article) return;

    try {
      if (isBookmarked) {
        await removeBookmark(article.id);
      } else {
        await addBookmark(article.id);
        analyticsService.logArticleBookmark({
          article_id: article.id,
          category: article.category?.name || 'Uncategorized',
          author: article.source_name || 'Unknown',
          source: article.source_name || 'Unknown',
          interaction_type: 'bookmark',
        });
      }
    } catch (e) {
      // Error is handled in the context, but we can log it here if needed
      console.error('Error toggling bookmark from hook:', e);
    }
  };

  return {
    article,
    loading,
    error,
    isBookmarked,
    isBookmarkLoading,
    toggleBookmark,
  };
};

import { useState } from 'react';
import { Alert } from 'react-native';
import { supabase } from '../utils/supabase';
import { handleGoogleSignIn } from '../utils/authHelpers';
import * as Linking from 'expo-linking';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { RootStackParamList } from '../types/navigation';

type NavigationProp = NativeStackNavigationProp<RootStackParamList, 'Login'>;

export const useAuth = () => {
  const navigation = useNavigation<NavigationProp>();
  const [email, setEmail] = useState('');
  const [password, setPassword] = useState('');
  const [isLoading, setIsLoading] = useState(false);

  const handleLogin = async () => {
    if (!email || !password) {
      Alert.alert('Error', 'Please enter both email and password.');
      return;
    }

    setIsLoading(true);
    try {
      const { data: { user }, error } = await supabase.auth.signInWithPassword({ email, password });

      if (error) {
        if (error.message.includes('Email not confirmed')) {
          Alert.alert(
            'Email Not Verified',
            'Please check your inbox to confirm your email address.'
          );
          navigation.navigate('EmailConfirmation', { email });
        } else {
          throw error;
        }
      } else if (user) {
        // Successful login
        navigation.reset({ index: 0, routes: [{ name: 'Main' }] });
      }
    } catch (error: any) {
      Alert.alert('Login Error', error.message || 'An unexpected error occurred.');
    } finally {
      setIsLoading(false);
    }
  };

  const handleSocialLogin = async () => {
    setIsLoading(true);
    try {
      await handleGoogleSignIn();
      // On success, the AuthContext listener should handle the navigation
    } catch (error: any) {
      // Error is handled by a toast in `handleGoogleSignIn`
      console.error('Social login error:', error);
    } finally {
      setIsLoading(false);
    }
  };

  const handleForgotPassword = async () => {
    if (!email) {
      Alert.alert('Error', 'Please enter your email to reset your password.');
      return;
    }

    setIsLoading(true);
    try {
      const { error } = await supabase.auth.resetPasswordForEmail(email, {
        redirectTo: Linking.createURL('auth/reset-password'),
      });
      if (error) throw error;
      Alert.alert('Password Reset', 'A password reset link has been sent to your email.');
    } catch (error: any) {
      Alert.alert('Error', error.message || 'Failed to send reset link.');
    } finally {
      setIsLoading(false);
    }
  };

  return {
    email,
    setEmail,
    password,
    setPassword,
    isLoading,
    handleLogin,
    handleSocialLogin,
    handleForgotPassword,
  };
};

import { useEffect, useCallback } from 'react';
import AsyncStorage from '@react-native-async-storage/async-storage';
import { supabase } from '../utils/supabase';
import { useAuth } from '../context/AuthContext';
import { toast } from 'sonner-native';
import { AuthChangeEvent } from '@supabase/supabase-js';

const SESSION_KEY = '@edushorts/auth_session';
const REFRESH_THRESHOLD = 60 * 60 * 1000; // 1 hour in milliseconds

export function useAuthSession() {
  const { refreshSession } = useAuth();

  const persistSession = useCallback(async () => {
    try {
      const { data: { session } } = await supabase.auth.getSession();
      if (session) {
        await AsyncStorage.setItem(SESSION_KEY, JSON.stringify({
          access_token: session.access_token,
          refresh_token: session.refresh_token,
          expires_at: session.expires_at,
        }));
      }
    } catch (error) {
      console.error('Error persisting session:', error);
    }
  }, []);

  const checkSession = useCallback(async (): Promise<boolean> => {
    try {
      const sessionStr = await AsyncStorage.getItem(SESSION_KEY);
      if (!sessionStr) return false;

      const session = JSON.parse(sessionStr);
      const expiresAt = new Date(session.expires_at).getTime();
      const now = Date.now();

      // If session is expired or will expire soon, refresh it
      if (expiresAt - now < REFRESH_THRESHOLD) {
        await refreshSession();
        await persistSession();
      }
      return true;
    } catch (error) {
      console.error('Error checking session:', error);
      // If there's an error, clear the stored session
      await AsyncStorage.removeItem(SESSION_KEY);
      return false;
    }
  }, [refreshSession, persistSession]);

  // Set up session persistence
  useEffect(() => {
    const { data: { subscription } } = supabase.auth.onAuthStateChange(async (event: AuthChangeEvent, session) => {
      switch (event) {
        case 'SIGNED_IN':
        case 'TOKEN_REFRESHED':
          await persistSession();
          break;
        case 'SIGNED_OUT':
          await AsyncStorage.removeItem(SESSION_KEY);
          break;
        case 'USER_UPDATED':
          if (!session) {
            // User was deleted
            await AsyncStorage.removeItem(SESSION_KEY);
            toast.error('Your account has been deleted');
          }
          break;
      }
    });

    // Check session on mount
    checkSession();

    // Set up periodic session checks
    const intervalId = setInterval(checkSession, REFRESH_THRESHOLD / 2);

    return () => {
      subscription.unsubscribe();
      clearInterval(intervalId);
    };
  }, [checkSession, persistSession]);

  return {
    checkSession,
    persistSession,
  };
}

// Custom hook for protected routes that require authentication
export function useRequireAuth(redirectTo: string = '/login') {
  const { session, isLoading } = useAuth();
  const { checkSession } = useAuthSession();

  useEffect(() => {
    if (!isLoading && !session) {
      checkSession().then((isValid) => {
        if (!isValid) {
          // Handle navigation to login
          // You might want to use your navigation logic here
          console.log('Redirect to:', redirectTo);
        }
      });
    }
  }, [session, isLoading, checkSession, redirectTo]);

  return {
    isAuthenticated: !!session,
    isLoading,
  };
}

import { useState, useCallback, useEffect } from 'react';
import { Article } from '../types/supabase';
import { newsService } from '../services/newsService';

export const useNewsFeed = () => {
  const [news, setNews] = useState<Article[]>([]);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const [hasMore, setHasMore] = useState(true);
  const [page, setPage] = useState(1);

  const fetchNews = useCallback(async (categoryId: string | null) => {
    setLoading(true);
    setError(null);
    try {
      const fetchedArticles = await newsService.getArticles({
        categoryId,
        page: 1,
        limit: 10,
      });
      setNews(fetchedArticles);
      setPage(2);
      setHasMore(fetchedArticles.length > 0);
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, []);

  const loadMoreNews = useCallback(async (categoryId: string | null) => {
    if (loading || !hasMore) return;
    setLoading(true);
    try {
      const fetchedArticles = await newsService.getArticles({
        categoryId,
        page,
        limit: 10,
      });

      if (fetchedArticles.length > 0) {
        setNews(prevNews => [...prevNews, ...fetchedArticles]);
        setPage(prevPage => prevPage + 1);
      } else {
        setHasMore(false);
      }
    } catch (e: any) {
      setError(e.message);
    } finally {
      setLoading(false);
    }
  }, [loading, hasMore, page]);

  return {
    news,
    loading,
    error,
    hasMore,
    setNews,
    fetchNews,
    loadMoreNews,
  };
};

import { useEffect } from 'react';
import { supabase, createChannel } from '../utils/supabase';
import { Article, NewsRow } from '../types/supabase';
import { RealtimePostgresChangesPayload } from '@supabase/supabase-js';

const newsRowToArticle = (newsRow: any): Article => ({
  ...newsRow,
  category: newsRow.categories,
});

export const useNewsRealtime = (
  setNews: React.Dispatch<React.SetStateAction<Article[]>>,
  currentCategoryId: string | null
) => {
  useEffect(() => {
    const handleRealtimeEvent = (
      payload: RealtimePostgresChangesPayload<NewsRow>
    ) => {
      if (payload.eventType === 'INSERT' && payload.new) {
        const newArticle = newsRowToArticle(payload.new);
        if (!currentCategoryId || newArticle.category_id === currentCategoryId) {
          setNews(prev => [newArticle, ...prev.filter(a => a.id !== newArticle.id)]);
        }
      } else if (payload.eventType === 'UPDATE' && payload.new) {
        const updatedArticle = newsRowToArticle(payload.new);
        setNews(prev =>
          prev.map(article =>
            article.id === updatedArticle.id ? updatedArticle : article
          )
        );
      } else if (payload.eventType === 'DELETE' && payload.old) {
        setNews(prev => prev.filter(article => article.id !== (payload.old as NewsRow).id));
      }
    };

    const { channel, cleanup } = createChannel('news-changes');

    channel
      .on<NewsRow>('postgres_changes', { event: '*', schema: 'public', table: 'news' }, (payload) =>
        handleRealtimeEvent(payload)
      );

    return () => {
      cleanup();
    };
  }, [currentCategoryId, setNews]);
};

import { useState, useEffect } from 'react';
import { PostgrestResponse, PostgrestSingleResponse, SupabaseClient } from '@supabase/supabase-js';
import { supabase } from '../utils/supabase';
import { useAuth } from '../context/AuthContext';

type SupabaseCountResult = {
  data: any[];
  error: null | {
    message: string;
    details: string;
    code: string;
  };
  count: number | null;
  status: number;
  statusText: string;
};

type CountQueryResponse = PostgrestResponse<any[]> & Partial<SupabaseCountResult>;

interface UserStats {
  savedArticlesCount: number;
  isLoading: boolean;
  error: Error | null;
  refresh: () => Promise<void>;
}

export function useUserStats(): UserStats {
  const { user } = useAuth();
  const [savedArticlesCount, setSavedArticlesCount] = useState(0);
  const [isLoading, setIsLoading] = useState(true);
  const [error, setError] = useState<Error | null>(null);

  const fetchStats = async (retryCount = 0, maxRetries = 2) => {
    if (!user) {
      setIsLoading(false);
      return;
    }

    try {
      setIsLoading(true);
      setError(null);

      // Create abort controller for timeout
      const savedController = new AbortController();

      // Set timeout
      const savedTimeout = setTimeout(() => savedController.abort(), 5000);

      try {
        // Execute query with abort signal
        const savedResult = await supabase
          .from('saved_articles')
          .select('*', { count: 'exact', head: true })
          .eq('user_id', user.id)
          .abortSignal(savedController.signal)
          .throwOnError();

        // Clear timeout
        clearTimeout(savedTimeout);

        // Handle the count with type assertion
        const savedCount = (savedResult as CountQueryResponse).count ?? 0;
        
        setSavedArticlesCount(savedCount);
      } finally {
        // Clean up controller
        savedController.abort();
      }

    } catch (err) {
      console.error('Error fetching user stats:', err);
      
      // Retry with exponential backoff if not maximum retries
      if (retryCount < maxRetries) {
        const delay = Math.min(1000 * Math.pow(2, retryCount), 5000);
        console.log(`Retrying user stats fetch in ${delay}ms...`);
        
        setTimeout(() => {
          fetchStats(retryCount + 1, maxRetries);
        }, delay);
        
        return;
      }

      setError(err instanceof Error ? err : new Error('Failed to fetch user stats'));
    } finally {
      setIsLoading(false);
    }
  };

  // Fetch stats on mount, when user changes, and set up refresh interval
  useEffect(() => {
    let isSubscribed = true;
    
    const loadStats = async () => {
      if (isSubscribed) {
        await fetchStats();
      }
    };

    loadStats();

    // Refresh stats every 2 minutes if the user is active
    const interval = setInterval(loadStats, 120000);

    return () => {
      isSubscribed = false;
      clearInterval(interval);
    };
  }, [user?.id]);

  return {
    savedArticlesCount,
    isLoading,
    error,
    refresh: fetchStats,
  };
}

