import React, { useState, useCallback, useEffect } from 'react';
import { supabase } from '../utils/supabase';
import {
  View,
  Text,
  StyleSheet,
  TextInput,
  FlatList,
  TouchableOpacity,
  Image,
  ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Feather } from '@expo/vector-icons';
import { useNavigation } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import { RootStackParamList } from '../types/navigation';
import { Article } from '../types/supabase';
import { useNews } from '../context/NewsContext';
import { ArticleResultCard } from '../components/ArticleResultCard';

// Debounce function
function debounce<F extends (...args: any[]) => any>(func: F, waitFor: number) {
  let timeout: ReturnType<typeof setTimeout> | null = null;

  const debounced = (...args: Parameters<F>) => {
    if (timeout !== null) {
      clearTimeout(timeout);
      timeout = null;
    }
    timeout = setTimeout(() => func(...args), waitFor);
  };

  return debounced as (...args: Parameters<F>) => ReturnType<F>;
}

export default function DiscoverScreen() {
  const navigation = useNavigation();
  const [searchQuery, setSearchQuery] = useState('');
  const [searchResults, setSearchResults] = useState<Article[]>([]);
  const [loading, setLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);

  const handleSearch = useCallback(async (text: string) => {
    setSearchQuery(text);
    setLoading(true);
    setError(null);

    try {
      let query = supabase
        .from('news')
        .select(`
          *,
          category:category_id (
            id,
            name
          )
        `)
        .eq('status', 'published')
        .order('created_at', { ascending: false });

      if (text.trim() !== '') {
        query = query.or(`title.ilike.%${text}%,summary.ilike.%${text}%,content.ilike.%${text}%`);
      }

      const { data, error } = await query.limit(20);
      if (error) throw error;
      setSearchResults(data as Article[] || []);
    } catch (error) {
      console.error('Error searching news:', error);
      setError(error instanceof Error ? error.message : 'An error occurred while searching');
      setSearchResults([]);
    } finally {
      setLoading(false);
    }
  }, []);

  const debouncedSearch = useCallback(debounce((text: string) => handleSearch(text), 500), [handleSearch]);

  useEffect(() => {
    handleSearch('');
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [handleSearch]);

  const renderItem = useCallback(({ item, index }: { item: Article; index: number }) => (
    <ArticleResultCard
      article={item}
      onPress={() => {
        const parentNavigator = navigation.getParent<NativeStackNavigationProp<RootStackParamList>>();
        if (parentNavigator) {
          parentNavigator.navigate('SingleArticleViewer', { 
            articleId: item.id,
            articles: searchResults, 
            currentIndex: index 
          });
        }
      }}
    />
  ), [navigation, searchResults]);

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()}>
          <Feather name="arrow-left" size={24} color="#333" />
        </TouchableOpacity>
        <Text style={styles.headerTitle}>Discover</Text>
        <View style={{ width: 24 }} />
      </View>

      <Text style={styles.subtitle}>Global news at your fingertips</Text>

