    color: '#ff0000',
    marginBottom: 32,
    textShadowColor: 'rgba(0, 0, 0, 0.1)',
    textShadowOffset: { width: 0, height: 1 },
    textShadowRadius: 2,
  },
  spinner: {
    transform: [{ scale: 1.75 }],
    marginBottom: 24,
  },
  loadingText: {
    fontSize: 18,
    color: '#666666',
    textAlign: 'center',
    marginTop: 12,
    letterSpacing: 0.5,
  },
  errorText: {
    color: '#ff0000',
    fontWeight: 'bold',
  },
});

