import React, { useState, useEffect, useRef } from 'react';
import {
  View,
  Text,
  StyleSheet,
  TouchableOpacity,
  ActivityIndicator,
} from 'react-native';
import { SafeAreaView } from 'react-native-safe-area-context';
import { Feather } from '@expo/vector-icons';
import { useNavigation, useRoute, RouteProp } from '@react-navigation/native';
import { NativeStackNavigationProp } from '@react-navigation/native-stack';
import PagerView from 'react-native-pager-view';
import { RootStackParamList } from '../types/navigation';
import { Article } from '../types/supabase';
import NewsCard from '../components/NewsCard';
import { supabase } from '../utils/supabase';

type SingleArticleViewerNavigationProp = NativeStackNavigationProp<
  RootStackParamList,
  'SingleArticleViewer'
>;

type SingleArticleViewerRouteProp = RouteProp<
  RootStackParamList,
  'SingleArticleViewer'
>;

export default function SingleArticleViewerScreen() {
  const navigation = useNavigation<SingleArticleViewerNavigationProp>();
  const route = useRoute<SingleArticleViewerRouteProp>();
  
  const { articleId: initialArticleId, articles: initialArticles, currentIndex: initialCurrentIndex } = route.params || {};

  const [displayArticles, setDisplayArticles] = useState<Article[]>([]);
  const [currentArticleIndex, setCurrentArticleIndex] = useState<number>(0);
  const [currentArticleForHeader, setCurrentArticleForHeader] = useState<Article | null>(null);
  const [loading, setLoading] = useState(true);
  const [error, setError] = useState<string | null>(null);
  const pagerRef = useRef<PagerView>(null);

  useEffect(() => {
    const loadContent = async () => {
      setLoading(true);
      setError(null);

      if (initialArticles && initialArticles.length > 0 && initialCurrentIndex !== undefined && initialCurrentIndex >= 0) {
        // Case 1: Navigating from Discover with a list of articles
        if (initialCurrentIndex < initialArticles.length) {
          setDisplayArticles(initialArticles);
          setCurrentArticleIndex(initialCurrentIndex);
          setCurrentArticleForHeader(initialArticles[initialCurrentIndex]);
        } else {
          setError('Invalid initial index provided.');
        }
      } else if (initialArticleId) {
        // Case 2: Navigating from a deep link with only an articleId
        try {
          const { data: articleData, error: fetchError } = await supabase
            .from('news')
            .select('*, category:category_id(id, name)')
            .eq('id', initialArticleId)
            .single();

          if (fetchError) throw fetchError;
          if (!articleData) throw new Error('Article not found.');

          setDisplayArticles([articleData as Article]);
          setCurrentArticleIndex(0);
          setCurrentArticleForHeader(articleData as Article);
        } catch (e) {
          console.error('Error fetching single article:', e);
          setError(e instanceof Error ? e.message : 'Failed to load article.');
          setDisplayArticles([]);
        }
      } else {
        setError('No article ID or article list provided.');
        setDisplayArticles([]);
      }
      setLoading(false);
    };

    loadContent();
  }, [initialArticleId, initialArticles, initialCurrentIndex]);

  useEffect(() => {
    // Update header when current article for header changes
    if (currentArticleForHeader) {
      navigation.setOptions({ headerTitle: currentArticleForHeader.title || 'Article' });
    }
  }, [currentArticleForHeader, navigation]);


  const handlePageSelected = (event: { nativeEvent: { position: number } }) => {
    const newIndex = event.nativeEvent.position;
    if (displayArticles && displayArticles[newIndex]) {
      setCurrentArticleIndex(newIndex);
      setCurrentArticleForHeader(displayArticles[newIndex]);
    }
  };

  if (loading) {
    return (
      <SafeAreaView style={styles.centered}>
        <ActivityIndicator size="large" color="#0066cc" />
      </SafeAreaView>
    );
  }

  if (error || !displayArticles || displayArticles.length === 0) {
    return (
      <SafeAreaView style={styles.centered}>
        <Text style={styles.errorText}>{error || 'No article to display.'}</Text>
        <TouchableOpacity
          style={styles.backButtonExternal}
          onPress={() => navigation.goBack()}
        >
          <Text style={styles.backButtonText}>Go Back</Text>
        </TouchableOpacity>
      </SafeAreaView>
    );
  }

  // Ensure initialPage is valid
  const validInitialPage = Math.max(0, Math.min(currentArticleIndex, displayArticles.length - 1));

  return (
    <SafeAreaView style={styles.container}>
      <View style={styles.header}>
        <TouchableOpacity onPress={() => navigation.goBack()} style={styles.headerButton}>
          <Feather name="arrow-left" size={24} color="#333" />
        </TouchableOpacity>
        <Text style={styles.headerTitle} numberOfLines={1} ellipsizeMode="tail">
          {currentArticleForHeader?.title || 'Article'}
        </Text>
        <View style={styles.headerButtonPlaceholder} /> 
      </View>
      <PagerView
        ref={pagerRef}
        style={styles.pagerView}
        initialPage={validInitialPage}
        orientation="vertical"
        onPageSelected={handlePageSelected}
        scrollEnabled={displayArticles.length > 1} // Disable swiping if only one article
        overdrag={false} // Keep as is, or set based on whether displayArticles.length > 1
      >
        {displayArticles.map((articleItem, index) => (
          <View key={articleItem.id || `article-${index}`} style={styles.pageContainerForNewsCard}>
            <NewsCard article={articleItem} />
          </View>
        ))}
      </PagerView>
    </SafeAreaView>
  );
}

const styles = StyleSheet.create({
  container: {
    flex: 1,
    backgroundColor: '#ffffff',
  },
  centered: {
    flex: 1,
    justifyContent: 'center',
    alignItems: 'center',
    padding: 20,
    backgroundColor: '#ffffff',
  },
  errorText: {
    fontSize: 16,
    color: 'red',
    marginBottom: 20,
    textAlign: 'center',
  },
  header: {
    flexDirection: 'row',
    justifyContent: 'space-between',
    alignItems: 'center',
    paddingHorizontal: 16,
    paddingVertical: 12,
    borderBottomWidth: 1,
    borderBottomColor: '#eee',
    backgroundColor: '#ffffff',
  },
  headerButton: {
    padding: 5, 
    justifyContent: 'center',
    alignItems: 'center',
  },
  headerButtonPlaceholder: {
    minWidth: 34, 
  },
  headerTitle: {
    flex: 1,
    textAlign: 'center',
    fontSize: 18,
    fontWeight: 'bold',
    color: '#333',
    marginHorizontal: 10,
  },
  backButtonExternal: {
    marginTop: 20,
    backgroundColor: '#0066cc',
    paddingHorizontal: 20,
    paddingVertical: 10,
    borderRadius: 6,
  },
  backButtonText: {
    color: 'white',
    fontWeight: 'bold',
  },
  pagerView: {
    flex: 1,
  },
  pageContainerForNewsCard: {
    flex: 1,
  },
});

import { supabase } from '../utils/supabase';
import type { Article } from '../types/supabase';
import { monitoringService } from '../services/monitoring';

interface MigrationStep {
  name: string;
  up: () => Promise<void>;
  down: () => Promise<void>;
  validate: () => Promise<ValidationResult>;
}

interface ValidationResult {
  status: 'success' | 'error';
  details: Record<string, any>;
  timestamp: string;
}

interface MigrationReport {
  startTime: string;
  endTime: string;
  steps: {
    name: string;
    status: 'success' | 'error';
    duration: number;
    error?: string;
  }[];
  validation: ValidationResult[];
}

class Migration {
  private steps: MigrationStep[] = [];
  private report: MigrationReport = {
    startTime: '',
    endTime: '',
    steps: [],
    validation: [],
  };

  async addStep(step: MigrationStep) {
    this.steps.push(step);
  }

  async execute(): Promise<MigrationReport> {
    this.report.startTime = new Date().toISOString();
    let error = null;

    try {
      for (const step of this.steps) {
        const startTime = Date.now();
        try {
          await step.up();
          const validationResult = await step.validate();
          this.report.validation.push(validationResult);

          if (validationResult.status === 'error') {
            throw new Error(`Validation failed for step: ${step.name}`);
          }

          this.report.steps.push({
            name: step.name,
            status: 'success',
            duration: Date.now() - startTime,
          });
        } catch (e: any) {
          error = e as Error;
          this.report.steps.push({
            name: step.name,
            status: 'error',
            duration: Date.now() - startTime,
            error: e.message,
          });
          // Attempt rollback
          await this.rollback(this.steps.indexOf(step));
          break;
        }
      }
    } finally {
      this.report.endTime = new Date().toISOString();
      await this.saveReport();
    }

    if (error) {
      throw error;
    }

    return this.report;
  }

  private async rollback(fromIndex: number) {
    // Rollback in reverse order
    for (let i = fromIndex; i >= 0; i--) {
      const step = this.steps[i];
      try {
        await step.down();
      } catch (e: any) {
        // Log rollback error but continue with other rollbacks
        console.error(`Rollback failed for step ${step.name}:`, e);
        await monitoringService.trackError({
          type: 'runtime',
          message: `Rollback failed for step ${step.name}`,
          stack: e.stack || '',
        });
      }
    }
  }

  private async saveReport() {
    try {
      await supabase
        .from('migration_logs')
        .insert([
          {
            report: this.report,
            created_at: new Date().toISOString(),
          },
        ]);
    } catch (e) {
      console.error('Failed to save migration report:', e);
      // Don't throw here as this is a non-critical operation
    }
  }
}

// Example migration step for articles
export const createArticleMigrationStep = (): MigrationStep => ({
  name: 'article_migration',
  up: async () => {
    const { data: articles, error } = await supabase
      .from('news')
      .select('*')
      .eq('status', 'published');

    if (error) throw error;

    // Process in batches to avoid memory issues
    const batchSize = 100;
    for (let i = 0; i < articles.length; i += batchSize) {
      const batch = articles.slice(i, i + batchSize);
      await processArticleBatch(batch);
    }
  },
  down: async () => {
    // Implement rollback logic
    await supabase.from('news').delete().gt('id', 0);
  },
  validate: async () => {
    const { count: sourceCount } = await supabase
      .from('news')
      .select('*', { count: 'exact', head: true });

    const { count: targetCount } = await supabase
      .from('articles')
      .select('*', { count: 'exact', head: true });

    return {
      status: sourceCount === targetCount ? 'success' : 'error',
      details: {
        sourceCount,
        targetCount,
        timestamp: new Date().toISOString(),
      },
      timestamp: new Date().toISOString(),
    };
  },
});

async function processArticleBatch(articles: Article[]) {
  const { error } = await supabase.from('articles').insert(
    articles.map((article) => ({
      ...article,
      migrated_at: new Date().toISOString(),
      migration_version: '1.0.0',
    }))
  );

  if (error) throw error;
}

// Export the Migration class for use in scripts
export default Migration;

import Migration, { createArticleMigrationStep } from './migration';
import { monitoringService } from '../services/monitoring';
import { supabase } from '../utils/supabase';

async function validateConnection() {
  try {
    const { data, error } = await supabase.from('news').select('id').limit(1);
    if (error) throw error;
    return true;
  } catch (error) {
    console.error('Failed to connect to Supabase:', error);
    return false;
  }
}

async function runMigration() {
  console.log('Starting news system migration...');

  // Validate database connection
  const isConnected = await validateConnection();
  if (!isConnected) {
    console.error('Database connection failed. Aborting migration.');
    process.exit(1);
  }

  const startTime = Date.now();
  
  try {
    const migration = new Migration();
    
    // Add migration steps
    await migration.addStep(createArticleMigrationStep());
    
    // Execute migration
    const report = await migration.execute();
    
    // Calculate duration
    const duration = Date.now() - startTime;
    
    // Log results
    console.log('\nMigration completed successfully');
    console.log('Duration:', Math.round(duration / 1000), 'seconds');
    console.log('Steps completed:', report.steps.length);
    console.log('Validation results:', report.validation.length);
    
    // Track successful migration
    await monitoringService.trackInteraction(
      'news_system_migration',
      duration,
      {
        status: 'success',
        startTime: report.startTime,
        endTime: report.endTime,
        stepCount: report.steps.length,
        validationResults: report.validation.map(v => v.status),
      }
    );

    // Print detailed report
    console.log('\nDetailed Report:');
    console.log(JSON.stringify(report, null, 2));
  } catch (error: any) {
    console.error('\nMigration failed:', error.message);
    
    // Track migration failure
    await monitoringService.trackError({
      type: 'runtime',
      message: 'News system migration failed',
      stack: error.stack || '',
    });
    
    process.exit(1);
  }
}

// Check if running directly (not imported)
if (require.main === module) {
  runMigration()
    .then(() => {
      console.log('Migration script completed');
      process.exit(0);
    })
    .catch((error) => {
      console.error('Unhandled error:', error);
      process.exit(1);
    });
}

import { getAnalytics, FirebaseAnalyticsTypes } from '@react-native-firebase/analytics';
import { ReactNativeFirebase } from '@react-native-firebase/app';
import {
  ANALYTICS_EVENTS,
  ArticleAnalyticsParams,
  AdAnalyticsParams,
  UserInteractionAnalyticsParams,
  ScreenViewAnalyticsParams,
  AnalyticsEventName,
  EventParams
} from '../src/types/analytics'; // Adjust path as needed

class AnalyticsService {
  private static instance: AnalyticsService;
  private firebaseApp: ReactNativeFirebase.FirebaseApp | null = null;
  private analyticsInstance: FirebaseAnalyticsTypes.Module | null = null;

  private constructor() {
    // Private constructor. Firebase-specific initialization deferred to `initialize`.
    // DO NOT call methods that rely on this.analyticsInstance here.
  }

  static getInstance(): AnalyticsService {
    if (!AnalyticsService.instance) {
      AnalyticsService.instance = new AnalyticsService();
    }
    return AnalyticsService.instance;
  }

  /**
   * Initializes the AnalyticsService with the Firebase App instance.
   * This MUST be called before any other analytics methods.
   * @param app The FirebaseApp instance.
   */
  async initialize(app: ReactNativeFirebase.FirebaseApp): Promise<void> {
    this.firebaseApp = app;
    this.analyticsInstance = getAnalytics(app); // Initialize analyticsInstance first
    
    // Now it's safe to call methods that use this.analyticsInstance
    await this.setAnalyticsCollectionEnabled(true); 

    if (__DEV__) {
      console.log('[AnalyticsService] Initialized with Firebase App.');
    }
  }

  // Helper to ensure analytics instance is available
  private getAnalyticsInstance(): FirebaseAnalyticsTypes.Module {
    if (!this.analyticsInstance) {
      console.error('[Analytics] Error: AnalyticsService not initialized. Call initialize() first.');
      throw new Error('AnalyticsService not initialized.');
    }
    return this.analyticsInstance;
  }

  /**
   * Generic method to log any analytics event.
   * @param name - The name of the event.
   * @param params - Optional parameters for the event.
   */
  async logEvent(name: AnalyticsEventName | string, params?: EventParams): Promise<void> {
    try {
      if (!name || typeof name !== 'string' || name.length > 40) {
        if (__DEV__) { console.warn(`[Analytics] Invalid event name: ${name}`); }
        return;
      }
      
      await this.getAnalyticsInstance().logEvent(name, params);
      if (__DEV__) { console.log(`[Analytics] Event logged: ${name}`, params || ''); }
    } catch (error) {
      if (__DEV__) { console.error(`[Analytics] Error logging event "${name}":`, error); }
    }
  }

  // --- Specific Event Logging Methods ---

  // Article Analytics
  async logArticleView(params: ArticleAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.ARTICLE_VIEW, params);
  }

  async logArticleShare(params: ArticleAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.ARTICLE_SHARE, params);
  }

  async logArticleBookmark(params: ArticleAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.ARTICLE_BOOKMARK, params);
  }
  
  async logArticleReadTime(params: ArticleAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.ARTICLE_READ_TIME, params);
  }
  
  async logArticleScroll(params: ArticleAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.ARTICLE_SCROLL, params);
  }

  // Advertisement Analytics
  async logAdImpression(params: AdAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.AD_IMPRESSION, params);
  }

  async logAdClick(params: AdAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.AD_CLICK, params);
  }
  
  async logAdViewComplete(params: AdAnalyticsParams): Promise<void> {
    await this.logEvent(ANALYTICS_EVENTS.AD_VIEW_COMPLETE, params);
  }
  
  async logAdSkip(params: AdAnalyticsParams): Promise<void> {
