// Create a safer version of the Branch SDK with fallbacks for all methods.
// This version dynamically requires 'react-native-branch'.default at call time.
const branchSDK = {
  init: async (...args: any[]) => {
    const currentBranchModule = require('react-native-branch').default;
    if (currentBranchModule && typeof currentBranchModule.init === 'function') {
      console.log('[DeepLinkHandler/branchSDK] Found and calling branch.init()');
      return currentBranchModule.init(...args);
    }
    // If branch.init() is not found on the JS module,
    // we assume native initialization is primary for session start.
    // The critical part for JS for deep linking is often branch.subscribe().
    console.log('[DeepLinkHandler/branchSDK] branch.init() not found on JS module. Proceeding, assuming native init is primary. Subscription will be attempted.');
    return Promise.resolve(); // Allow flow to continue to subscribe
  },
  debug: async (...args: any[]) => {
    const currentBranchModule = require('react-native-branch').default;
    if (currentBranchModule && typeof currentBranchModule.debug === 'function') {
      return currentBranchModule.debug(...args);
    }
    // No warning for debug usually
    return Promise.resolve();
  },
  subscribe: (callback: (payload: { error: Error | null; params: BranchParams | null; uri: string | null }) => void) => {
    const currentBranchModule = require('react-native-branch').default;
    if (currentBranchModule && typeof currentBranchModule.subscribe === 'function') {
      return currentBranchModule.subscribe(callback);
    }
    console.warn('Branch subscribe not available [Component Stack] - (Direct require check)');
    return () => {}; // Return a no-op unsubscribe function
  },
  createBranchUniversalObject: async (...args: any[]) => {
    const currentBranchModule = require('react-native-branch').default;
    if (currentBranchModule && typeof currentBranchModule.createBranchUniversalObject === 'function') {
      return currentBranchModule.createBranchUniversalObject(...args);
    }
    console.warn('Branch createBranchUniversalObject not available [Component Stack] - (Direct require check)');
    // Return a fallback BUO that produces a fallback URL
    return {
      generateShortUrl: async () => ({ url: 'https://play.google.com/store/apps/details?id=com.ajilkojilgokulravi.unniman' })
    };
  },
  userCompletedAction: (...args: any[]) => {
    const currentBranchModule = require('react-native-branch').default;
    if (currentBranchModule && typeof currentBranchModule.userCompletedAction === 'function') {
      return currentBranchModule.userCompletedAction(...args);
    }
    // If not immediately available, try again after a very short delay.
    console.warn('Branch userCompletedAction not immediately available (Direct require check). Attempting a delayed retry (100ms).');
    setTimeout(() => {
      const freshBranchModule = require('react-native-branch').default; // Re-require here too for the retry
      if (freshBranchModule && typeof freshBranchModule.userCompletedAction === 'function') {
        console.log('[DeepLinkHandler/branchSDK] userCompletedAction became available on retry (Direct require). Executing action.');
        freshBranchModule.userCompletedAction(...args);
      } else {
        console.warn('[DeepLinkHandler/branchSDK] userCompletedAction still not available after delayed retry (Direct require). The action may not have been tracked by Branch.');
      }
    }, 100);
  }
};

interface BranchParams {
  '+clicked_branch_link'?: boolean;
  articleId?: string;
  [key: string]: any;
}

interface BranchSubscribeParams {
  error: Error | null;
  params: BranchParams | null;
  uri: string | null;
}

class DeepLinkHandler {
  private static instance: DeepLinkHandler;
  private navigationRef: any;
  private branchUnsubscribe: (() => void) | null = null;
  private initialized: boolean = false;
  private maxInitAttempts: number = 3;
  private initAttempts: number = 0;
  private initDelay: number = 1000; // 1 second between retries

  private constructor() {
    // Private constructor for singleton pattern
  }

  static getInstance(): DeepLinkHandler {
    if (!DeepLinkHandler.instance) {
      DeepLinkHandler.instance = new DeepLinkHandler();
    }
    return DeepLinkHandler.instance;
  }

  setNavigationRef(ref: any) {
    this.navigationRef = ref;
  }

  createDeepLink(path: string, params: Record<string, string> = {}): string {
    const prefix = Platform.select({
      ios: 'edushorts://',
      android: 'edushorts://',
      default: 'edushorts://'
    });

    return Linking.createURL(path, { queryParams: params });
  }

  async handleDeepLink(url: string): Promise<boolean> {
    try {
      const parsedUrl = Linking.parse(url);

      if (!parsedUrl.path) {
        return false;
      }

      const pathParts = parsedUrl.path.split('/');

      // Handle article deep links
      if (pathParts[0] === 'articles' && pathParts[1]) {
        const articleId = pathParts[1];
        this.navigateToArticle(articleId);
        return true;
      }

      return false;
    } catch (error) {
      console.error('Error handling deep link:', error);
      return false;
    }
  }

  private navigateToArticle(articleId: string): void {
    if (!this.navigationRef?.current) {
      console.error('Navigation ref not set');
      return;
    }

    try {
      this.navigationRef.current.navigate('SingleArticleViewer', { 
        articleId,
        fromDeepLink: true 
      });
    } catch (error) {
      console.error('Error navigating to article:', error);
    }
  }

  async initialize(): Promise<void> {
    if (this.initialized) {
      return;
    }

    try {
      // Check if Branch SDK is available
      if (Platform.OS !== 'web' && NativeModules.RNBranch) {
        await this.initializeBranchWithRetry();
      } else {
        console.log('Branch SDK not available on this platform or not properly linked');
      }

      // Set up URL handling for non-Branch deep links
      await this.setupURLHandling();

      this.initialized = true;
    } catch (error) {
      console.error('Error initializing DeepLinkHandler:', error);
      throw error;
    }
  }

  private async initializeBranchWithRetry(): Promise<void> {
    while (this.initAttempts < this.maxInitAttempts) {
      try {
        this.initAttempts++;
        console.log(`Attempting Branch SDK initialization (Attempt ${this.initAttempts}/${this.maxInitAttempts})`);

        await branchSDK.init();
        if (__DEV__) {
          await branchSDK.debug(true);
        }

        this.branchUnsubscribe = branchSDK.subscribe(({ error, params, uri }: BranchSubscribeParams) => {
          if (error) {
            if (!error.toString().includes('Session initialization already happened')) {
                console.error('Branch deep link error from subscribe:', error);
                this.logBranchError(error, 'subscribe_callback_init_retry');
            }
            return;
          }

          if (params && params['+clicked_branch_link']) {
            const articleId = params.articleId || params.article_id || null;
            if (articleId) {
              console.log('[DeepLinkHandler/initializeBranchWithRetry] Branch link clicked, navigating to article:', articleId);
              this.navigateToArticle(articleId);
            } else if (uri) {
              console.log('[DeepLinkHandler/initializeBranchWithRetry] Branch link clicked with URI, attempting to handle:', uri);
              this.handleDeepLink(uri); 
            }
          } else if (uri && !params?.['+clicked_branch_link']) {
            console.log('[DeepLinkHandler/initializeBranchWithRetry] Received URI via Branch subscribe (not a clicked Branch link), attempting to handle:', uri);
            this.handleDeepLink(uri);
          }
        });

        console.log('Branch SDK initialized and subscribed successfully via initializeBranchWithRetry.');
        return; 
      } catch (error) {
        console.error(`Branch SDK initialization attempt ${this.initAttempts} failed:`, error);
        if (this.initAttempts < this.maxInitAttempts) {
          await new Promise(resolve => setTimeout(resolve, this.initDelay));
        } else {
          throw new Error('Failed to initialize Branch SDK after multiple attempts');
        }
      }
    }
  }

  private async setupURLHandling(): Promise<void> {
    try {
      // Handle incoming links when app is not running
      const url = await Linking.getInitialURL();
      if (url) {
        this.handleDeepLink(url);
      }

      // Handle incoming links when app is running
      Linking.addEventListener('url', ({ url }) => {
        if (url) {
          this.handleDeepLink(url);
        }
      });
    } catch (error) {
      console.error('Error setting up URL handling:', error);
    }
  }

  setupDeepLinkListeners(): void {
    try {
      // Handle deep links when the app is already open (Expo Linking)
      Linking.addEventListener('url', ({ url }) => {
        if (url) {
          console.log('[DeepLinkHandler/setupDeepLinkListeners] Expo Linking event received:', url);
          this.handleDeepLink(url); // Assumes handleDeepLink can process non-Branch URLs too
        }
      });

      // Handle deep links when the app is launched from a deep link (Expo Linking)
      Linking.getInitialURL().then((url) => {
        if (url) {
          console.log('[DeepLinkHandler/setupDeepLinkListeners] Expo Linking initial URL:', url);
          this.handleDeepLink(url); // Assumes handleDeepLink can process non-Branch URLs too
        }
      }).catch(error => {
        console.error('Error getting initial URL (Expo Linking):', error);
        // this.logBranchError(error, 'getInitialURL_expo_linking'); // Decide if this specific logging is needed
      });

      // Branch initialization and deep link handling has been moved to initializeBranchWithRetry
      // The following Branch-specific code is removed from here to prevent duplicate initialization:
      // if (__DEV__) { ... branchSDK.debug(true); ... }
      // if (typeof branchSDK.subscribe !== 'function') { ... }
      // if (this.branchUnsubscribe) { ... this.branchUnsubscribe(); ... }
      // try { branchSDK.init({ forceNewSession: true }); ... this.branchUnsubscribe = branchSDK.subscribe(...); ... } catch { ... }

      console.log('[DeepLinkHandler/setupDeepLinkListeners] Generic Expo Linking listeners are set up. Branch listeners are handled via initialize().');

    } catch (setupError) {
      console.error('Error setting up generic deep link listeners:', setupError);
      // this.logBranchError(setupError, 'setupDeepLinkListeners_expo_linking_overall');
    }
  }

  cleanupBranchListeners(): void {
    // Clean up Branch listener when component unmounts
    if (this.branchUnsubscribe) {
      this.branchUnsubscribe();
      this.branchUnsubscribe = null;
    }
  }

  async verifyDeepLinkConfiguration(): Promise<boolean> {
    try {
      const supportedSchemes = await Linking.getInitialURL();
      return !!supportedSchemes;
    } catch (error) {
      console.error('Error verifying deep link configuration:', error);
      this.logBranchError(error, 'verifyDeepLinkConfiguration');
      return false;
    }
  }

  parseArticleId(deepLink: string): string | null {
    try {
      const parsedUrl = Linking.parse(deepLink);
      const pathParts = parsedUrl.path?.split('/');

      if (pathParts?.[0] === 'articles' && pathParts[1]) {
        return pathParts[1];
      }

      return null;
    } catch (error) {
      console.error('Error parsing article ID from deep link:', error);
      return null;
    }
  }

  /**
   * Creates a Branch.io deep link for sharing an article
   * @param articleId The ID of the article to share
   * @param title The title of the article
   * @param description Optional description or summary of the article
   * @param imageUrl Optional image URL for the article
   * @returns A promise that resolves to the generated Branch link
   */
  async createBranchLink(
    articleId: string, 
    title: string, 
    description?: string,
    imageUrl?: string
  ): Promise<string> {
    try {
      // Generate a truly unique identifier using UUID v4
      const uniqueId = `article-${articleId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}`;

      // Create Branch Universal Object with unique ID
      const branchUniversalObject = await branchSDK.createBranchUniversalObject(uniqueId, {
        locallyIndex: true,
        title,
        contentDescription: description,
        contentImageUrl: imageUrl,
        contentMetadata: {
          customMetadata: {
            articleId: articleId.toString(),
            timestamp: Date.now().toString()
          }
        }
      });

      // Define link properties
      const linkProperties = {
        feature: 'share',
        channel: 'app',
        campaign: 'article-sharing',
      };

      // Define control parameters with fallback URLs
      const controlParams = {
        $desktop_url: `https://play.google.com/store/apps/details?id=com.ajilkojilgokulravi.unniman`,
        $android_url: 'market://details?id=com.ajilkojilgokulravi.unniman',
        $ios_url: 'https://apps.apple.com/app/id123456789', // Replace with actual App Store ID
        $fallback_url: `https://play.google.com/store/apps/details?id=com.ajilkojilgokulravi.unniman`,
        data: {
          articleId: articleId.toString()
        }
      };

      // Generate short URL with retries
      let attempts = 0;
      const maxAttempts = 3;

      while (attempts < maxAttempts) {
        try {
          const { url } = await branchUniversalObject.generateShortUrl(linkProperties, controlParams);
          console.log('Successfully created Branch link:', url);
          return url;
        } catch (generateError) {
          attempts++;
          if (attempts === maxAttempts) {
            throw generateError;
          }
          // Wait a short time before retrying
          await new Promise(resolve => setTimeout(resolve, 1000));
          // Generate a new unique ID for retry
          const retryId = `article-${articleId}-${Date.now()}-${Math.random().toString(36).substr(2, 9)}-retry${attempts}`;
          await branchUniversalObject.setCanonicalIdentifier(retryId);
        }
      }

      throw new Error('Failed to generate Branch link after multiple attempts');
    } catch (error) {
      console.error('Error creating Branch link:', error);
      return `https://play.google.com/store/apps/details?id=com.ajilkojilgokulravi.unniman`;
    }
  }

  /**
   * Creates a Branch.io deep link specifically for notifications
   * @param articleId The ID of the article to link to
   * @param title The notification title
   * @param notificationId Optional notification ID for tracking
   * @returns A promise that resolves to the generated Branch link
   */
  async createNotificationDeepLink(
    articleId: string,
    title: string,
    notificationId?: string
  ): Promise<string> {
    try {
      // Create a Branch Universal Object
      const branchUniversalObject = await branchSDK.createBranchUniversalObject(`article/${articleId}`, {
        locallyIndex: true,
        title,
        contentMetadata: {
          customMetadata: {
            articleId,
            source: 'notification',
            ...(notificationId ? { notificationId } : {})
          }
        }
      });

      // Define link properties specific to notifications
      const linkProperties = {
        feature: 'notification',
        channel: 'push',
        campaign: 'article_notification'
      };

      // Define control parameters
      const controlParams = {
        $desktop_url: `https://play.google.com/store/apps/details?id=com.ajilkojilgokulravi.unniman`,
        articleId,
        source: 'notification'
      };

      // Generate the link
      const { url } = await branchUniversalObject.generateShortUrl(linkProperties, controlParams);
      return url;
    } catch (error) {
      console.error('Error creating notification Branch link:', error);
      // Fallback to a direct deep link
      return `edushorts://articles/${articleId}`;
    }
  }

  /**
   * Track an article share with Branch analytics
   * @param articleId The ID of the shared article
   * @param channel The sharing channel used (e.g., 'facebook', 'twitter', 'whatsapp')
   */
  trackArticleShare(articleId: string, channel: string = 'unknown'): void {
    try {
      if (typeof branchSDK.userCompletedAction === 'function') {
        branchSDK.userCompletedAction('share_article_custom', {
          articleId,
          channel,
        });
      } else {
        console.warn('branchSDK.userCompletedAction is not a function, cannot track article share.');
        this.logBranchError(new Error('branchSDK.userCompletedAction not a function'), 'trackArticleShare');
      }
    } catch (error) {
      console.error('Error tracking article share event:', error);
      this.logBranchError(error, 'trackArticleShare');
    }
  }

  /**
   * Track an article view with Branch analytics
   * @param articleId The ID of the viewed article
   * @param source Source of the article view (e.g., 'share', 'notification', 'search')
   */
  trackArticleView(articleId: string, source: string = 'app'): void {
    try {
      if (typeof branchSDK.userCompletedAction === 'function') {
        branchSDK.userCompletedAction('view_article_custom', {
          articleId,
          source,
        });
      } else {
        console.warn('branchSDK.userCompletedAction is not a function, cannot track article view.');
        this.logBranchError(new Error('branchSDK.userCompletedAction not a function'), 'trackArticleView');
      }
    } catch (error) {
      console.error('Error tracking article view event:', error);
      this.logBranchError(error, 'trackArticleView');
    }
  }

  // Utility method for logging Branch related errors
  private logBranchError(error: any, context: string): void {
    const message = error instanceof Error ? error.message : String(error);
    console.error(`Branch SDK Error | Context: ${context} | Message: ${message}`, error);

    // Placeholder for a more sophisticated error reporting service
    // e.g., Sentry.captureException(error, { tags: { branchContext: context } });
    const errorMonitor = (global as any).ErrorMonitor;
    if (typeof errorMonitor?.captureException === 'function') {
      try {
        errorMonitor.captureException(error, {
          tags: {
            context: 'branch_sdk',
            operation: context
          }
        });
      } catch (monitoringError) {
        console.error('Failed to send error to monitoring service:', monitoringError);
      }
    }
  }

  // Utility method to check if Branch SDK seems initialized (optional usage)
  private async waitForBranchInitialization(timeoutMs = 5000): Promise<boolean> {
    const localBranchInstance = require('react-native-branch').default; // Use a local require

    if (localBranchInstance && typeof localBranchInstance.getLatestReferringParams === 'function') {
      // If this function exists, Branch native module is likely available and initialized.
      // This doesn't guarantee session data is ready, but it's a good basic check.
      try {
        // A light check - this doesn't guarantee a session, but confirms SDK is responsive.
        await localBranchInstance.getLatestReferringParams(); 
        return true;
      } catch (e) {
        // Could be an error if called too early, or SDK not ready.
        this.logBranchError(e, 'waitForBranchInitialization_getLatestReferringParams');
      }
    }

    // Fallback to polling if the above check isn't sufficient or fails
    return new Promise((resolve) => {
      const startTime = Date.now();
      const interval = setInterval(() => {
        const currentBranchModule = require('react-native-branch').default; // Re-require for fresh check
        // Check for a function that indicates Branch might be ready
        // Adjust this check based on a reliable indicator from the Branch SDK
        if (currentBranchModule && typeof currentBranchModule.subscribe === 'function' && typeof currentBranchModule.createBranchUniversalObject === 'function') {
          clearInterval(interval);
          resolve(true);
        } else if (Date.now() - startTime > timeoutMs) {
          clearInterval(interval);
          this.logBranchError(new Error('Timeout waiting for Branch SDK initialization'), 'waitForBranchInitialization_timeout');
          resolve(false);
        }
      }, 200);
    });
  }
}

export default DeepLinkHandler;

import { NOTIFICATION_CONFIG } from '../constants/config';
import type { NotificationType, DeliveryStatus } from '../constants/config';
import { supabase } from '../utils/supabase';

interface NotificationMetrics {
  deliveryStats: {
    totalSent: number;
    delivered: number;
    failed: number;
    retried: number;
  };
  
  tokenHealth: {
    validTokens: number;
    expiredTokens: number;
    refreshAttempts: number;
    refreshSuccess: number;
  };
  
  syncStatus: {
    lastSyncTime: Date;
    pendingUpdates: number;
    failedSync: number;
    retryCount: number;
  };
}

interface HealthCheckResult {
  status: 'healthy' | 'degraded' | 'failed';
  timestamp: Date;
  details: {
    expo: boolean;
    adminPanel: boolean;
    database: boolean;
  };
}

interface HealthIssue {
  type: 'error' | 'warning';
  component: 'expo' | 'admin-panel' | 'database' | 'notification';
  message: string;
  timestamp: Date;
}

class MonitoringService {
  private static instance: MonitoringService;
  private metrics: NotificationMetrics;
  private healthCheckInterval: NodeJS.Timeout | null = null;
  
  private constructor() {
    this.metrics = {
      deliveryStats: {
        totalSent: 0,
        delivered: 0,
        failed: 0,
        retried: 0
      },
      tokenHealth: {
        validTokens: 0,
        expiredTokens: 0,
        refreshAttempts: 0,
        refreshSuccess: 0
      },
      syncStatus: {
        lastSyncTime: new Date(),
        pendingUpdates: 0,
        failedSync: 0,
        retryCount: 0
      }
    };
  }

  static getInstance(): MonitoringService {
    if (!MonitoringService.instance) {
      MonitoringService.instance = new MonitoringService();
    }
    return MonitoringService.instance;
  }

  async initialize(): Promise<void> {
    await this.loadInitialMetrics();
    this.startHealthChecks();
  }

  private async loadInitialMetrics(): Promise<void> {
    try {
      // Load metrics from persistent storage if available
      const { data, error } = await supabase
        .from('monitoring_metrics')
        .select('*')
        .single();

      if (data && !error) {
        this.metrics = {
          ...this.metrics,
          ...data
        };
      }
    } catch (error) {
      console.error('Failed to load initial metrics:', error);
    }
  }

  private startHealthChecks(): void {
    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
    }

    this.healthCheckInterval = setInterval(
      async () => {
        await this.performHealthCheck();
      },
      NOTIFICATION_CONFIG.monitoring.healthCheckInterval
    );
  }

  async checkExpoConnection(): Promise<boolean> {
    try {
      const response = await fetch(NOTIFICATION_CONFIG.expo.apiUrl, {
        method: 'GET',
        headers: {
          'Authorization': `Bearer ${NOTIFICATION_CONFIG.expo.accessToken}`
        }
      });
      return response.ok;
    } catch (error) {
      console.error('Expo connection check failed:', error);
      return false;
    }
  }

  async validateAdminPanelSync(): Promise<boolean> {
    try {
      const { error } = await supabase
        .from('notifications')
        .select('count', { count: 'exact' })
        .limit(1);
      
      return !error;
    } catch (error) {
      console.error('Admin panel sync validation failed:', error);
      return false;
    }
  }

  async verifyDatabaseConnection(): Promise<boolean> {
    try {
      const { error } = await supabase.rpc('ping');
      return !error;
    } catch (error) {
      console.error('Database connection verification failed:', error);
      return false;
    }
  }

  private async performHealthCheck(): Promise<HealthCheckResult> {
    const details = {
      expo: await this.checkExpoConnection(),
      adminPanel: await this.validateAdminPanelSync(),
      database: await this.verifyDatabaseConnection()
    };

    const status = this.determineHealthStatus(details);
    const result = {
      status,
      timestamp: new Date(),
      details
    };

    await this.handleHealthCheckResult(result);
    return result;
  }

  private determineHealthStatus(details: HealthCheckResult['details']): HealthCheckResult['status'] {
    const services = Object.values(details);
    const failedCount = services.filter(status => !status).length;

    if (failedCount === 0) return 'healthy';
    if (failedCount < services.length) return 'degraded';
    return 'failed';
  }

  private async handleHealthCheckResult(result: HealthCheckResult): Promise<void> {
    if (result.status !== 'healthy') {
      const issues = this.generateHealthIssues(result);
      await this.alertOnCriticalIssues(issues);
    }
  }

  private generateHealthIssues(result: HealthCheckResult): HealthIssue[] {
    const issues: HealthIssue[] = [];
    const timestamp = new Date();

    if (!result.details.expo) {
      issues.push({
        type: 'error',
        component: 'expo',
        message: 'Expo service connection failed',
        timestamp
      });
    }

    if (!result.details.adminPanel) {
      issues.push({
        type: 'error',
        component: 'admin-panel',
        message: 'Admin panel sync failed',
        timestamp
      });
    }

    if (!result.details.database) {
      issues.push({
        type: 'error',
        component: 'database',
        message: 'Database connection failed',
        timestamp
      });
    }

    return issues;
  }

  async alertOnCriticalIssues(issues: HealthIssue[]): Promise<void> {
    try {
      await supabase
        .from('monitoring_alerts')
        .insert(issues.map(issue => ({
          type: issue.type,
          component: issue.component,
          message: issue.message,
          created_at: issue.timestamp
        })));
    } catch (error) {
      console.error('Failed to store monitoring alerts:', error);
    }
  }

  async updateMetrics(updates: Partial<NotificationMetrics>): Promise<void> {
    this.metrics = {
      ...this.metrics,
      ...updates
    };

    try {
      await supabase
        .from('monitoring_metrics')
        .upsert([{
          ...this.metrics,
          updated_at: new Date()
        }]);
    } catch (error) {
      console.error('Failed to update metrics:', error);
    }
  }

  async generateHealthReport(): Promise<{
    metrics: NotificationMetrics;
    lastHealthCheck: HealthCheckResult;
  }> {
    const lastHealthCheck = await this.performHealthCheck();
    return {
      metrics: this.metrics,
      lastHealthCheck
    };
  }

  cleanup(): void {
    if (this.healthCheckInterval) {
      clearInterval(this.healthCheckInterval);
      this.healthCheckInterval = null;
    }
  }
}

export default MonitoringService;

import { NOTIFICATION_CONFIG, NOTIFICATION_TYPES, DELIVERY_STATUS } from '../constants/config';
import type { NotificationType, DeliveryStatus } from '../constants/config';
import { supabase } from '../utils/supabase';
import MonitoringService from './MonitoringService';
import DeepLinkHandler from './DeepLinkHandler';
// import type { RemoteMessage as FirebaseRemoteMessage } from '@react-native-firebase/messaging'; // Original
import { FirebaseMessagingTypes } from '@react-native-firebase/messaging'; // New import strategy
import * as Notifications from 'expo-notifications';

// Import Branch with a fallback in case of errors
let branch: any;
try {
  branch = require('react-native-branch').default;
} catch (error) {
  console.error('Error importing Branch SDK in NotificationBridge:', error);
  // Create a minimal fallback
  branch = {
    openURL: (url: string) => {
      console.warn('Branch SDK not available, cannot open URL:', url);
      return Promise.resolve(false);
    }
  };
}

interface NotificationPayload {
  type: NotificationType;
  payload: {
    title: string;
    body: string;
    deep_link?: string;
    data?: Record<string, unknown>;
  };
}

interface DeliveryStatusUpdate {
  notificationId: string;
  status: DeliveryStatus;
  timestamp: Date;
}

class NotificationBridge {
  private static instance: NotificationBridge;
  private monitoring: MonitoringService;
  private retryQueue: Map<string, { payload: NotificationPayload; attempts: number }>;

  private constructor() {
    this.monitoring = MonitoringService.getInstance();
    this.retryQueue = new Map();
  }

  static getInstance(): NotificationBridge {
    if (!NotificationBridge.instance) {
      NotificationBridge.instance = new NotificationBridge();
    }
    return NotificationBridge.instance;
  }

  async initialize(): Promise<void> {
    await this.setupRealtimeSubscription();
    this.startRetryProcessor();
    const { status: existingStatus } = await Notifications.getPermissionsAsync();
    let finalStatus = existingStatus;
    if (existingStatus !== 'granted') {
      const { status } = await Notifications.requestPermissionsAsync();
      finalStatus = status;
    }
    if (finalStatus !== 'granted') {
      console.warn('Failed to get push notification permissions for NotificationBridge!');
    }
  }

  private setupRealtimeSubscription(): void {
    const channel = supabase.channel('notifications');
    channel
      .on(
        'postgres_changes',
        {
          event: 'INSERT',
          schema: 'public',
          table: 'notifications'
        },
        this.handleNewNotification.bind(this)
      )
      .subscribe();
  }

  private async handleNewNotification(payload: { new: any }): Promise<void> {
    const notification = this.transformNotification(payload.new);
    await this.processNotification(notification);
  }

  private transformNotification(rawNotification: any): NotificationPayload {
    return {
      type: rawNotification.type as NotificationType,
      payload: {
        title: rawNotification.title,
        body: rawNotification.body,
        deep_link: rawNotification.deep_link,
        data: rawNotification.data
      }
    };
  }

  async processNotification(notification: NotificationPayload): Promise<void> {
    try {
      const currentMetrics = this.monitoring['metrics'].deliveryStats;
      await this.monitoring.updateMetrics({
        deliveryStats: {
          totalSent: currentMetrics.totalSent + 1,
          delivered: currentMetrics.delivered,
          failed: currentMetrics.failed,
          retried: currentMetrics.retried
        }
      });

      switch (notification.type) {
        case NOTIFICATION_TYPES.PUSH:
          await this.handlePushNotification(notification);
          break;
        case NOTIFICATION_TYPES.SCHEDULED:
          await this.handleScheduledNotification(notification);
          break;
        case NOTIFICATION_TYPES.ARTICLE_LINK:
          await this.handleArticleLinkNotification(notification);
          break;
        case NOTIFICATION_TYPES.WEB:
          await this.handleWebNotification(notification);
          break;
        default:
          console.warn(`Unhandled notification type: ${notification.type}`);
      }
    } catch (error: unknown) {
      console.error('Error processing notification:', error instanceof Error ? error.message : error);
      await this.handleDeliveryFailure(notification);
    }
  }

  private async handlePushNotification(notification: NotificationPayload): Promise<void> {
    try {
      // Process deep link if present
      if (notification.payload.deep_link) {
        this.handleDeepLink(notification.payload.deep_link);
      }
      
      const expoToken = await this.getExpoToken();
      if (!expoToken) {
        throw new Error('No Expo push token available');
      }
      
      const response = await fetch(NOTIFICATION_CONFIG.expo.apiUrl, {
        method: 'POST',
        headers: {
          'Authorization': `Bearer ${NOTIFICATION_CONFIG.expo.accessToken}`,
          'Content-Type': 'application/json',
        },
        body: JSON.stringify({
          to: expoToken,
          title: notification.payload.title,
          body: notification.payload.body,
          data: {
            ...notification.payload.data,
            // Include the deep link in the data payload for FCM
            ...(notification.payload.deep_link ? { deep_link: notification.payload.deep_link } : {})
          }
        })
      });

      // Comprehensive status code validation
      if (!response.ok) {
        let errorMessage = `Push notification failed: ${response.status} ${response.statusText}`;
        
        try {
          const errorBody = await response.text();
          if (errorBody) {
            errorMessage += ` - ${errorBody}`;
          }
        } catch (parseError) {
          // If we can't parse the error body, use the status text
        }
        
        throw new Error(errorMessage);
      }

      // Validate response body
      try {
        const responseData = await response.json();
        if (responseData.errors && responseData.errors.length > 0) {
          console.warn('Expo push notification warnings:', responseData.errors);
        }
      } catch (jsonError) {
        console.warn('Could not parse push notification response as JSON');
      }

      await this.updateDeliveryStatus({
        notificationId: notification.payload.data?.id as string,
        status: DELIVERY_STATUS.DELIVERED,
        timestamp: new Date()
      });
    } catch (error: unknown) {
      throw new Error(`Push notification delivery failed: ${error instanceof Error ? error.message : String(error)}`);
    }
  }

  // Helper method to handle deep links
  private handleDeepLink(deepLink: string): void {
    try {
      // If it's a Branch link (starts with the Branch domain)
      if (deepLink.includes('xbwk1.app.link') || deepLink.includes('xbwk1-alternate.app.link')) {
        // Use Branch SDK directly to open URL
        branch.openURL(deepLink);
      } else if (deepLink.startsWith('edushorts://')) {
        // Handle standard deep links using our DeepLinkHandler
        DeepLinkHandler.getInstance().handleDeepLink(deepLink);
      } else {
        // For any other URL, attempt to open it
        DeepLinkHandler.getInstance().handleDeepLink(deepLink);
      }
    } catch (error) {
      console.error('Error handling deep link from notification:', error);
    }
  }

  private async handleScheduledNotification(notification: NotificationPayload): Promise<void> {
    // Store the notification for later delivery
    const scheduledTime = notification.payload.data?.scheduledFor as string;
    if (!scheduledTime) {
      throw new Error('Scheduled notification missing scheduledFor time');
    }

    await supabase
      .from('scheduled_notifications')
      .insert({
        notification: notification,
        scheduled_for: scheduledTime,
        status: DELIVERY_STATUS.PENDING
      });
  }

  private async handleArticleLinkNotification(notification: NotificationPayload): Promise<void> {
    // Ensure the deep link is properly formatted
    if (!notification.payload.deep_link?.startsWith('edushorts://articles/')) {
      throw new Error('Invalid article deep link format');
    }

    await this.handlePushNotification({
      ...notification,
      type: NOTIFICATION_TYPES.PUSH
    });
  }

  private async handleWebNotification(notification: NotificationPayload): Promise<void> {
    // Web notifications are handled differently - they're shown in the app's UI
    await supabase
      .from('web_notifications')
      .insert({
        title: notification.payload.title,
        body: notification.payload.body,
        data: notification.payload.data,
        created_at: new Date()
      });
  }

  private async handleDeliveryFailure(notification: NotificationPayload): Promise<void> {
    const notificationId = notification.payload.data?.id as string;
    const currentAttempts = this.retryQueue.get(notificationId)?.attempts || 0;

    if (currentAttempts < NOTIFICATION_CONFIG.monitoring.retryAttempts) {
      this.retryQueue.set(notificationId, {
        payload: notification,
        attempts: currentAttempts + 1
      });

      const currentMetrics = this.monitoring['metrics'].deliveryStats;
      await this.monitoring.updateMetrics({
        deliveryStats: {
          totalSent: currentMetrics.totalSent,
          delivered: currentMetrics.delivered,
          failed: currentMetrics.failed + 1,
          retried: currentMetrics.retried + 1
        }
      });
    } else {
      await this.updateDeliveryStatus({
        notificationId,
        status: DELIVERY_STATUS.FAILED,
        timestamp: new Date()
      });

      this.retryQueue.delete(notificationId);
    }
  }

  private startRetryProcessor(): void {
    setInterval(async () => {
      for (const [id, { payload, attempts }] of this.retryQueue) {
        try {
          await this.processNotification(payload);
          this.retryQueue.delete(id);
        } catch (error: unknown) {
          console.error(`Retry attempt ${attempts} failed for notification ${id}:`, 
            error instanceof Error ? error.message : error);
        }
      }
    }, 60000); // Process retry queue every minute
  }

  async getExpoToken(): Promise<string> {
    const { data: profile } = await supabase.auth.getUser();
    if (!profile?.user?.id) {
      throw new Error('No authenticated user');
    }

    const { data: userProfile } = await supabase
      .from('profiles')
      .select('notification_preferences')
      .eq('id', profile.user.id)
      .single();

    const expoToken = userProfile?.notification_preferences?.expo_token;
    if (!expoToken) {
      throw new Error('No Expo push token found');
    }

    return expoToken;
  }

  async updateDeliveryStatus(update: DeliveryStatusUpdate): Promise<void> {
    try {
      await supabase
        .from('notifications')
        .update({
          status: update.status,
          updated_at: update.timestamp
        })
        .eq('id', update.notificationId);

      if (update.status === DELIVERY_STATUS.DELIVERED) {
        const currentMetrics = this.monitoring['metrics'].deliveryStats;
        await this.monitoring.updateMetrics({
          deliveryStats: {
            totalSent: currentMetrics.totalSent,
            delivered: currentMetrics.delivered + 1,
            failed: currentMetrics.failed,
            retried: currentMetrics.retried
          }
        });
      }
    } catch (error: unknown) {
      console.error('Failed to update delivery status:', error);
      throw error;
    }
  }

  cleanup(): void {
    // Clean up any subscriptions or intervals
    clearInterval(this.startRetryProcessor as unknown as number);
  }

  /**
   * Handles an FCM message received directly by the app.
   * This method processes both notification and data messages from FCM and displays them using expo-notifications.
   * @param remoteMessage The FCM message received from @react-native-firebase/messaging
   */
  async handleReceivedFcmMessage(remoteMessage: FirebaseMessagingTypes.RemoteMessage): Promise<void> {
    console.log('NotificationBridge: handleReceivedFcmMessage', JSON.stringify(remoteMessage, null, 2));
    try {
      // Extract notification data, prioritizing notification fields over data fields
      const notificationData = {
        title: remoteMessage.notification?.title || remoteMessage.data?.title || 'New Notification',
        body: remoteMessage.notification?.body || remoteMessage.data?.body || remoteMessage.data?.message || '',
        deep_link: (remoteMessage.data?.deep_link || remoteMessage.data?.url || remoteMessage.data?.click_action || '').toString(),
        // Preserve all original data for potential use
        originalData: remoteMessage.data || {},
        messageId: remoteMessage.messageId,
        // Include additional FCM-specific fields if present
        channelId: remoteMessage.notification?.android?.channelId,
      };

      // Handle deep link if present
      if (notificationData.deep_link) {
        this.handleDeepLink(notificationData.deep_link);
      }

      // Map FCM priority to a string priority value if present
      let priority: string | undefined;
      if (remoteMessage.notification?.android?.priority) {
        switch (remoteMessage.notification.android.priority) {
          case FirebaseMessagingTypes.NotificationAndroidPriority.PRIORITY_HIGH:
          case FirebaseMessagingTypes.NotificationAndroidPriority.PRIORITY_MAX:
            priority = 'high';
            break;
          case FirebaseMessagingTypes.NotificationAndroidPriority.PRIORITY_LOW:
          case FirebaseMessagingTypes.NotificationAndroidPriority.PRIORITY_MIN:
            priority = 'low';
            break;
          default:
            priority = 'default';
        }
      }

      // Ensure all data values are strings
      const sanitizedData = Object.entries(notificationData).reduce((acc, [key, value]) => ({
        ...acc,
        [key]: typeof value === 'string' ? value : value?.toString() || ''
      }), {});

      // Schedule the notification using expo-notifications
      const notificationId = await Notifications.scheduleNotificationAsync({
        content: {
          title: String(notificationData.title),
          body: String(notificationData.body),
          data: sanitizedData,
          sound: 'default',
          // If we have an Android channel ID from FCM, use it
          ...(notificationData.channelId && { android: { channelId: notificationData.channelId } }),
          // Include priority if mapped
          ...(priority && { priority }),
        },
        trigger: null, // Display immediately
      });

      console.log('NotificationBridge: FCM notification scheduled with expo-notifications, ID:', notificationId);

      // Update delivery status if we have a message ID
      if (remoteMessage.messageId) {
        await this.updateDeliveryStatus({
          notificationId: remoteMessage.messageId,
          status: DELIVERY_STATUS.DELIVERED,
          timestamp: new Date()
        });
      }

    } catch (error) {
      console.error('NotificationBridge: Error in handleReceivedFcmMessage:', error);
      // If we have a message ID, update the delivery status as failed
      if (remoteMessage.messageId) {
        await this.handleDeliveryFailure({
          type: NOTIFICATION_TYPES.PUSH,
          payload: {
            title: remoteMessage.notification?.title || '',
            body: remoteMessage.notification?.body || '',
            data: { id: remoteMessage.messageId }
          }
        });
      }
      // Re-throw the error for upstream handling
      throw error;
    }
  }
}

export default NotificationBridge;

